      "tipo": "DrawCalls",
      "causa_raiz": "O volume de Draw Calls atingiu picos de 20.492 chamadas por quadro, excedendo em quase 8 vezes o orçamento de 2.579 chamadas. Isso sobrecarrega o driver gráfico e a GPU (atingindo 43.89 ms), decorrente da ausência de agrupamento estático/dinâmico de malhas, instanciamento por GPU desativado nos materiais e grande quantidade de objetos individuais desenhados separadamente.",
      "codigo_refatorado": "using UnityEngine;

public class RuntimeMeshCombiner : MonoBehaviour
{
    [ContextMenu("Combinar Malhas Estáticas")]
    public void CombineMeshes()
    {
        MeshFilter[] meshFilters = GetComponentsInChildren<MeshFilter>();
        CombineInstance[] combine = new CombineInstance[meshFilters.Length];
        Material commonMaterial = null;

        int validMeshCount = 0;
        for (int i = 0; i < meshFilters.Length; i++)
        {
            if (meshFilters[i].sharedMesh == null || meshFilters[i].gameObject == gameObject) continue;

            MeshRenderer renderer = meshFilters[i].GetComponent<MeshRenderer>();
            if (renderer == null || !renderer.enabled) continue;

            if (commonMaterial == null)
            {
                commonMaterial = renderer.sharedMaterial;
            }
            else if (renderer.sharedMaterial != commonMaterial)
            {
                continue;
            }

            combine[validMeshCount].mesh = meshFilters[i].sharedMesh;
            combine[validMeshCount].transform = meshFilters[i].transform.localToWorldMatrix;
            meshFilters[i].gameObject.SetActive(false);
            validMeshCount++;
        }

        if (validMeshCount == 0) return;

        CombineInstance[] finalCombine = new CombineInstance[validMeshCount];
        System.Array.Copy(combine, finalCombine, validMeshCount);

        Mesh combinedMesh = new Mesh();
        combinedMesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
        combinedMesh.CombineMeshes(finalCombine, true, true);

        MeshFilter mf = gameObject.GetComponent<MeshFilter>() ?? gameObject.AddComponent<MeshFilter>();
        MeshRenderer mr = gameObject.GetComponent<MeshRenderer>() ?? gameObject.AddComponent<MeshRenderer>();

        mf.sharedMesh = combinedMesh;
        mr.sharedMaterial = commonMaterial;
    }
}",
      "explicacao_didatica": "Cada objeto desenhado na tela exige um comando enviado pela CPU para a GPU chamado Draw Call. Ter mais de 20 mil desses comandos faz a placa de vídeo passar mais tempo esperando ordens do que realmente desenhando o jogo. O código acima agrupa vários objetos estáticos que compartilham o mesmo material em uma única malha combinada, reduzindo centenas ou milhares de comandos para apenas uma chamada."
    }
  ],
  "dicas_level_design": "1. Habilite 'GPU Instancing' em todos os materiais aplicados a objetos repetidos (como árvores, pedras, grama e postes).
2. Marque todos os objetos fixos do cenário como 'Batching Static' no Inspector para permitir o Static Batching automático da Unity.
3. Configure malhas com LOD (Level of Detail), ocultando ou simplificando geometrias distantes.
4. Utilize Texture Atlasing para combinar várias texturas em um único material compartilhado, permitindo que diferentes objetos usem a mesma chamada de desenho.
5. Configure e teste Occlusion Culling (Window > Rendering > Occlusion Culling) para garantir que objetos escondidos atrás de paredes ou montanhas não sejam submetidos à GPU."
}

